window.CORSO={"id":"RSPP-A","titolo":"RSPP e ASPP – Modulo A","sottotitolo":"Corso di base per responsabili e addetti del servizio di prevenzione e protezione: approccio alla prevenzione, soggetti, valutazione dei rischi, misure, emergenze, sorveglianza sanitaria, consultazione e formazione","ore":28,"rif":"Art. 32 D.lgs. 81/2008 · Accordo Stato-Regioni 17 aprile 2025, Parte II, punto 5.2","soglia":70,"aggiornato":"2026-11","moduli":[{"id":"M0","titolo":"Introduzione","min":10,"foto":"aziende","schermate":[{"t":"copertina","tit":"RSPP e ASPP – Modulo A","sott":"Corso di 28 ore · e-learning, aula e videoconferenza sincrona","nar":"Benvenuti al Modulo A del percorso per responsabili e addetti del servizio di prevenzione e protezione. È il corso di base, propedeutico ai moduli B e C, e costituisce credito formativo permanente. L'Accordo Stato-Regioni del diciassette aprile duemilaventicinque ne fissa la durata in ventotto ore, articolate in cinque unità didattiche.","p":1},{"t":"obiettivi","tit":"Obiettivi formativi","voci":["Comprendere l'approccio alla prevenzione del D.lgs. 81/2008 e il sistema delle responsabilità","Conoscere ruoli, compiti e responsabilità dei soggetti del sistema di prevenzione aziendale","Padroneggiare il processo di valutazione dei rischi e i contenuti del DVR","Conoscere DPI, segnaletica, gestione delle emergenze e sorveglianza sanitaria","Organizzare consultazione, informazione, formazione e addestramento"],"nar":"Il modulo fornisce le basi giuridiche e tecniche del ruolo: l'approccio alla prevenzione, i soggetti del sistema aziendale, il processo di valutazione dei rischi, le misure di protezione, le emergenze, la sorveglianza sanitaria, la consultazione e la formazione dei lavoratori.","p":1}]},{"id":"M1","titolo":"Unità A1 · L'approccio alla prevenzione nel D.lgs. 81/2008","min":470,"foto":"chi","schermate":[{"t":"sezione","tit":"Unità A1","sott":"L'approccio alla prevenzione nel D.lgs. 81/2008","nar":"Unità A uno. La filosofia della norma, il sistema delle fonti, le responsabilità e il sistema istituzionale della prevenzione.","p":0.6},{"t":"testo","tit":"Dalla tutela reattiva alla prevenzione organizzata","rif":"D.P.R. 547/1955 · D.lgs. 626/1994 · L. 123/2007 · D.lgs. 81/2008","lead":"La normativa è passata da un modello prescrittivo, fondato su requisiti tecnici, a un modello di prevenzione organizzata, fondato sulla valutazione dei rischi e sulla partecipazione.","punti":["Anni Cinquanta: D.P.R. 547/1955 e 303/1956, norme tecniche prescrittive","Recepimento delle direttive europee: D.lgs. 626/1994, valutazione dei rischi e servizio di prevenzione","L. 123/2007: delega per il Testo unico","D.lgs. 81/2008 e correttivo D.lgs. 106/2009: sistema unitario, prevenzione come processo gestionale","Riforme recenti: L. 215/2021, D.L. 19/2024, D.L. 159/2025, Accordo Stato-Regioni 17/04/2025"],"nar":"La sicurezza sul lavoro in Italia è passata da norme tecniche prescrittive, come quelle degli anni cinquanta, a un modello di prevenzione organizzata introdotto dalle direttive europee e dal decreto seicentoventisei del millenovecentonovantaquattro. Il Testo unico del duemilaotto ha riunito la disciplina in un sistema coerente, in cui la prevenzione è un processo gestionale fondato sulla valutazione dei rischi e sulla partecipazione. Le riforme più recenti hanno rafforzato vigilanza, formazione e controllo degli appalti.","p":1.6},{"foto":false,"t":"laboratorio","tit":"Laboratorio · Da reattivo a preventivo","lead":"Analizzi come un’impresa di 70 lavoratori gestisce oggi la sicurezza e proponi il passaggio a un approccio preventivo.","dossier":[["Oggi","si interviene dopo gli infortuni; il DVR è un documento redatto una volta e archiviato; i quasi incidenti non si registrano"],["Risorse","RSPP esterno 8 giorni l’anno; preposti non formati"],["Obiettivo della direzione","ridurre gli infortuni del 30% in due anni"]],"compiti":[{"q":"Quali segnali indicano un approccio reattivo?","min":6,"modello":"Interventi solo dopo gli eventi; DVR statico e non usato; assenza di dati sui quasi incidenti; preposti non formati; nessun indicatore proattivo.","criteri":["Ho elencato i segnali reattivi"]},{"q":"Proponi cinque azioni per un approccio preventivo.","min":8,"modello":"Registrazione e analisi dei quasi incidenti; DVR come strumento vivo con programma delle misure monitorato; formazione e individuazione dei preposti; sopralluoghi periodici della direzione; riunioni brevi di reparto e indicatori proattivi.","criteri":["Ho proposto azioni organizzative","Ho collegato DVR e programma","Ho previsto indicatori proattivi"],"minc":120},{"q":"Come misuri il raggiungimento dell’obiettivo?","min":6,"modello":"Indice di frequenza e numero di infortuni rispetto all’anno base, insieme a indicatori proattivi come quasi incidenti segnalati e azioni chiuse: la riduzione degli infortuni deve essere accompagnata da una crescita delle attività preventive.","criteri":["Ho indicato l’indicatore di risultato","Ho collegato indicatori proattivi"]}],"nar":"Nel laboratorio analizzi un’impresa che gestisce la sicurezza in modo reattivo e proponi il passaggio a un approccio preventivo, con azioni e indicatori. Confronta ogni risposta con la soluzione di riferimento.","rif":"Art. 15 D.lgs. 81/2008 · UNI EN ISO 45001","est":true,"ancora":"Dalla tutela reattiva alla prevenzione organizzata"},{"t":"testo","tit":"Il quadro europeo: la direttiva quadro e le direttive particolari","foto":false,"lead":"Il sistema italiano di prevenzione deriva in larga parte dal diritto dell’Unione europea, che fissa prescrizioni minime per la salute e sicurezza dei lavoratori (art. 153 TFUE).","punti":["Direttiva 89/391/CEE (direttiva quadro): obbligo generale di sicurezza, principi generali di prevenzione, valutazione dei rischi, servizi di prevenzione, informazione, consultazione e formazione","Direttive particolari (art. 16 della direttiva quadro): luoghi di lavoro, attrezzature, DPI, movimentazione manuale, videoterminali, agenti chimici, cancerogeni, biologici, agenti fisici, cantieri, segnaletica","Direttive di prodotto (mercato interno): macchine, DPI, apparecchiature ATEX, sostanze chimiche (REACH e CLP)","Recepimento in Italia: D.lgs. 626/1994 e successive norme di settore, riunite e riordinate dal D.lgs. 81/2008","Strategia dell’Unione in materia di salute e sicurezza sul lavoro 2021-2027: anticipare i cambiamenti, migliorare la prevenzione, aumentare la preparazione alle crisi"],"appro":"Le direttive sociali fissano requisiti minimi: gli Stati membri possono mantenere o introdurre misure più protettive. Le direttive di prodotto realizzano invece un’armonizzazione completa: lo Stato non può imporre requisiti diversi per l’immissione sul mercato. Questa distinzione spiega perché il datore di lavoro risponde dell’uso sicuro anche di prodotti conformi.","rif":"Art. 153 TFUE · Direttiva 89/391/CEE · D.lgs. 81/2008","nar":"Il sistema italiano di prevenzione deriva in larga parte dal diritto europeo. La direttiva quadro del 1989 ha fissato i principi generali: valutazione dei rischi, servizi di prevenzione, informazione, consultazione e formazione. Le direttive particolari riguardano i singoli rischi, mentre quelle di prodotto disciplinano macchine, dispositivi di protezione individuale e sostanze. In Italia il recepimento è passato dal decreto 626 del 1994 al Testo unico del 2008.","p":1.6},{"foto":false,"t":"testo","tit":"I principi generali di prevenzione della Direttiva 89/391/CEE","lead":"La direttiva quadro ha fissato i principi che il D.lgs. 81/2008 riprende nelle misure generali di tutela dell’art. 15.","punti":["Evitare i rischi e valutare quelli che non possono essere evitati","Combattere i rischi alla fonte e adeguare il lavoro all’uomo","Tenere conto del grado di evoluzione della tecnica; sostituire ciò che è pericoloso","Programmare una prevenzione coerente che integri tecnica, organizzazione, condizioni di lavoro e relazioni sociali","Dare priorità alla protezione collettiva e impartire adeguate istruzioni ai lavoratori"],"appro":"La direttiva ha introdotto l’obbligo generale di valutazione dei rischi, la partecipazione equilibrata dei lavoratori e i servizi di prevenzione: il cuore del modello italiano.","rif":"Dir. 89/391/CEE, artt. 5 e 6 · D.lgs. 81/2008, art. 15","nar":"La direttiva quadro ottantanove barra trecentonovantuno del Consiglio, del dodici giugno millenovecentoottantanove, è il fondamento del sistema europeo di salute e sicurezza sul lavoro. L’articolo sei elenca i principi generali di prevenzione che il datore di lavoro deve applicare. Il primo è evitare i rischi; quelli che non possono essere evitati vanno valutati. Occorre poi combattere i rischi alla fonte e adeguare il lavoro all’uomo, in particolare per quanto riguarda la concezione dei posti di lavoro, la scelta delle attrezzature e dei metodi di lavoro, per attenuare il lavoro monotono e ripetitivo. Si deve tenere conto del grado di evoluzione della tecnica, sostituire ciò che è pericoloso con ciò che non lo è o lo è meno, programmare la prevenzione in modo coerente, integrando tecnica, organizzazione del lavoro, condizioni di lavoro, relazioni sociali e influenza dei fattori ambientali. La protezione collettiva ha la priorità su quella individuale, e ai lavoratori vanno impartite istruzioni adeguate. La direttiva ha introdotto anche l’obbligo generale di valutare i rischi, la designazione di lavoratori incaricati della prevenzione, l’informazione, la consultazione e la partecipazione equilibrata dei lavoratori. Il decreto legislativo ottantuno del duemilaotto riprende questi principi nelle misure generali di tutela dell’articolo quindici; le direttive particolari disciplinano i singoli rischi.","est":true,"ancora":"Il quadro europeo: la direttiva quadro e le direttive particolari"},{"foto":false,"t":"laboratorio","tit":"Laboratorio · Dalla direttiva al decreto","lead":"Ricostruisci il percorso da una direttiva europea all’obbligo applicato in azienda.","dossier":[["Esempio","direttiva sugli agenti cancerogeni e mutageni, modificata più volte, da ultimo con la Dir. (UE) 2022/431 e la Dir. (UE) 2024/869"],["Recepimento","D.lgs. 135/2024 per i reprotossici e i nuovi valori limite"],["Azienda","verniciatura con prodotti contenenti composti del piombo"]],"compiti":[{"q":"Che differenza c’è tra direttiva e regolamento europeo?","min":5,"modello":"La direttiva vincola gli Stati sul risultato e va recepita con una norma nazionale; il regolamento è direttamente applicabile in tutti gli Stati, come il REACH e il CLP.","criteri":["Ho distinto direttiva e regolamento","Ho fatto esempi"]},{"q":"Come arriva l’obbligo in azienda nel caso del piombo?","min":7,"modello":"La direttiva introduce nuovi valori limite e include i reprotossici; il decreto di recepimento modifica il Titolo IX e i suoi allegati; l’azienda aggiorna la valutazione, applica il Capo II ai reprotossici e i nuovi valori limite, aggiorna sorveglianza e registro degli esposti.","criteri":["Ho descritto i passaggi","Ho indicato le conseguenze per l’azienda"]},{"q":"Come si tiene aggiornato un RSPP sulle novità europee?","min":6,"modello":"Monitorando Gazzetta ufficiale dell’Unione e Gazzetta ufficiale italiana, le pubblicazioni del Ministero del Lavoro e dell’INAIL, le norme tecniche armonizzate; registrando le novità in un registro delle prescrizioni con impatto e azioni.","criteri":["Ho indicato fonti ufficiali","Ho previsto un registro delle novità"]}],"nar":"Nel laboratorio ricostruisci il percorso da una direttiva europea all’obbligo in azienda, con l’esempio del piombo: differenza tra direttiva e regolamento, passaggi del recepimento e aggiornamento professionale. Confronta ogni risposta con la soluzione di riferimento.","rif":"TFUE, art. 288 · D.lgs. 135/2024","est":true,"ancora":"Il quadro europeo: la direttiva quadro e le direttive particolari"},{"foto":false,"t":"laboratorio","tit":"Laboratorio · Applicare i principi generali di prevenzione","lead":"Applichi i principi generali della direttiva quadro a un reparto di confezionamento con postazioni ripetitive.","dossier":[["Reparto","12 addette al confezionamento manuale, 8 ore con due pause"],["Problemi","movimenti ripetitivi, piani di lavoro fissi, ritmo imposto dal nastro, disturbi agli arti superiori segnalati dal medico competente"],["Proposta iniziale","fornire polsiere a tutte le addette"]],"compiti":[{"q":"Perché la proposta iniziale contrasta con i principi?","min":6,"modello":"Perché parte dai DPI o da ausili individuali invece di combattere il rischio alla fonte e adeguare il lavoro all’uomo; la protezione individuale viene dopo le misure collettive e organizzative.","criteri":["Ho richiamato l’ordine dei principi","Ho criticato la soluzione individuale"]},{"q":"Applica i principi: evitare, combattere alla fonte, adeguare il lavoro all’uomo.","min":8,"modello":"Evitare: automatizzare le fasi più ripetitive. Alla fonte: ridurre forza e frequenza con attrezzi e layout migliori. Adeguare all’uomo: piani regolabili, ritmo non imposto o regolabile, alternanza di compiti, pause più frequenti.","criteri":["Ho applicato i tre principi","Ho proposto misure concrete"],"minc":120},{"q":"Applica gli altri principi: evoluzione della tecnica, pianificazione, priorità collettiva, istruzioni.","min":7,"modello":"Valutare soluzioni tecniche nuove disponibili; pianificare la prevenzione integrando organizzazione e condizioni di lavoro; privilegiare misure collettive; fornire istruzioni e formazione adeguate.","criteri":["Ho applicato i principi restanti","Ho collegato la pianificazione"]},{"q":"Come verifichi l’efficacia?","min":6,"modello":"Nuova valutazione del sovraccarico biomeccanico con un metodo riconosciuto; andamento dei disturbi segnalati dal medico competente; percezione delle addette raccolta con l’RLS.","criteri":["Ho previsto una nuova valutazione","Ho previsto indicatori sanitari e di percezione"]}],"nar":"Nel laboratorio applichi i principi generali di prevenzione della direttiva quadro a un reparto di confezionamento, partendo da una proposta iniziale sbagliata. Confronta ogni risposta con la soluzione di riferimento.","rif":"Direttiva 89/391/CEE, art. 6 · art. 15 D.lgs. 81/2008","est":true,"ancora":"I principi generali di prevenzione della Direttiva 89/391/CEE"},{"t":"testo","tit":"L’evoluzione legislativa italiana","foto":false,"lead":"Dalla tutela fondata su prescrizioni tecniche si è passati alla prevenzione come processo organizzato e partecipato.","punti":["Costituzione: artt. 32 (salute), 35 (tutela del lavoro), 41 (l’iniziativa economica non può svolgersi in modo da recare danno alla salute e alla sicurezza)","Codice civile, art. 2087: norma di chiusura dell’obbligo di sicurezza","Anni Cinquanta: D.P.R. 547/1955 (prevenzione infortuni), D.P.R. 303/1956 (igiene del lavoro), D.P.R. 164/1956 (costruzioni): impostazione prescrittiva","L. 300/1970, art. 9: diritto dei lavoratori di controllare l’applicazione delle norme; L. 833/1978: competenze del Servizio sanitario nazionale","D.lgs. 626/1994: valutazione dei rischi, servizio di prevenzione, RLS; D.lgs. 81/2008 e correttivo D.lgs. 106/2009: Testo unico; L. 215/2021 e D.L. 159/2025: rafforzamento della vigilanza e della formazione"],"appro":"La modifica dell’art. 41 della Costituzione con la L. cost. 1/2022 ha inserito espressamente la salute e l’ambiente tra i limiti all’iniziativa economica. L’evoluzione mostra il passaggio dalla regola tecnica imposta al dovere di valutare e organizzare: il datore di lavoro non è soltanto tenuto a rispettare prescrizioni, ma a ricercare le misure che, secondo l’esperienza e la tecnica, sono necessarie (art. 2087 c.c.).","rif":"Artt. 32, 35, 41 Cost. · art. 2087 c.c. · L. 300/1970 · L. 833/1978 · D.lgs. 626/1994 · D.lgs. 81/2008","nar":"La tutela della salute nel lavoro ha radici nella Costituzione: gli articoli 32, 35 e 41, quest’ultimo modificato nel 2022 per includere espressamente salute e ambiente. Il codice civile, con l’articolo 2087, contiene la norma di chiusura. Negli anni Cinquanta i decreti avevano un’impostazione prescrittiva; con il decreto 626 del 1994 e poi con il Testo unico del 2008 la prevenzione è diventata un processo organizzato e partecipato.","p":1.6},{"foto":false,"t":"esempio","tit":"Esempio guidato · Le tappe della normativa italiana","lead":"Dalla Costituzione al Testo unico aggiornato.","passi":[["1948","La Costituzione tutela la salute e il lavoro e limita l’iniziativa economica (artt. 32, 35, 41).","Principi costituzionali"],["Anni Cinquanta","D.P.R. 547/1955 e 303/1956: norme tecniche prescrittive.","Approccio prescrittivo"],["1994","D.lgs. 626/1994: recepimento della direttiva quadro e valutazione dei rischi.","Approccio organizzativo"],["2008","D.lgs. 81/2008: Testo unico, sistema di prevenzione aziendale.","Testo unico"],["Dal 2021","Riforme su preposto, cantieri, formazione: D.L. 146/2021, D.L. 19/2024, Accordo 2025, D.L. 159/2025.","Aggiornamenti continui"]],"nar":"Ripercorriamo le tappe della normativa italiana. La Costituzione del quarantotto tutela salute e lavoro. Negli anni cinquanta arrivano norme tecniche prescrittive. Nel novantaquattro il decreto seicentoventisei introduce la valutazione dei rischi. Nel duemilaotto il Testo unico organizza il sistema di prevenzione. Dal duemilaventuno le riforme rafforzano preposto, cantieri e formazione.","rif":"Costituzione · D.lgs. 626/1994 · D.lgs. 81/2008","est":true,"ancora":"L’evoluzione legislativa italiana"},{"t":"testo","tit":"Normazione tecnica e principio di precauzione","foto":false,"lead":"Le norme tecniche sono specifiche volontarie elaborate dagli enti di normazione; diventano rilevanti per la legge quando questa vi rinvia o quando forniscono presunzione di conformità.","punti":["Enti di normazione: UNI e CEI in Italia; CEN e CENELEC in Europa; ISO e IEC a livello internazionale","Norme armonizzate: pubblicate nella Gazzetta ufficiale dell’Unione europea, conferiscono presunzione di conformità ai requisiti delle direttive o dei regolamenti di prodotto","Norme tecniche e buone prassi nel D.lgs. 81/2008 (art. 2, c. 1, lett. u e v): strumenti per adempiere agli obblighi","Le norme UNI in materia di salute e sicurezza comprese nella convenzione tra Ministero del Lavoro e UNI sono consultabili gratuitamente","Principio di precauzione (art. 191 TFUE): in presenza di incertezza scientifica su un rischio grave si adottano misure proporzionate senza attendere la piena prova del danno"],"appro":"Il riferimento all’edizione vigente della norma è essenziale: le norme vengono riviste periodicamente (ad esempio UNI EN ISO 3691-1:2020, UNI EN 280-1:2022, UNI ISO 12480-1:2024). Nelle valutazioni e nei documenti si cita l’edizione applicata. Il principio di precauzione orienta, ad esempio, la gestione delle nanoparticelle o dei nuovi agenti chimici privi di valori limite.","rif":"Art. 2, c. 1, lett. u) e v) D.lgs. 81/2008 · Reg. (UE) 1025/2012 · art. 191 TFUE","nar":"Le norme tecniche sono volontarie, ma diventano rilevanti quando la legge vi rinvia o quando, se armonizzate, danno presunzione di conformità ai requisiti europei. In Italia operano UNI e CEI, in Europa CEN e CENELEC, nel mondo ISO e IEC. Le norme UNI di sicurezza comprese nella convenzione con il Ministero del Lavoro sono consultabili gratuitamente. Il principio di precauzione chiede di agire con misure proporzionate anche in presenza di incertezza scientifica su un rischio grave.","p":1.6},{"foto":false,"t":"laboratorio","tit":"Laboratorio · Norma armonizzata e presunzione di conformità","lead":"Un costruttore di macchine italiano progetta una cesoia per lamiera e ti chiede come usare le norme tecniche.","dossier":[["Macchina","cesoia a ghigliottina idraulica"],["Riferimenti","regolamento macchine (UE) 2023/1230 applicabile dal 20 gennaio 2027; direttiva 2006/42/CE fino ad allora"],["Norme","UNI EN ISO 12100 per la valutazione del rischio; norma di tipo C specifica per le cesoie"]],"compiti":[{"q":"Che cosa significa presunzione di conformità?","min":6,"modello":"Se la macchina è progettata secondo norme armonizzate pubblicate nella Gazzetta ufficiale dell’Unione, si presume conforme ai requisiti essenziali coperti da quelle norme. Le norme restano volontarie: si può seguire un’altra strada dimostrando la conformità.","criteri":["Ho spiegato la presunzione","Ho ricordato la volontarietà"]},{"q":"Come si usano insieme le norme di tipo A, B e C?","min":7,"modello":"Tipo A, come la UNI EN ISO 12100: principi generali di valutazione e riduzione del rischio. Tipo B: aspetti di sicurezza comuni, come distanze di sicurezza o dispositivi di interblocco. Tipo C: requisiti specifici per la cesoia, che prevalgono sulle altre per i pericoli trattati.","criteri":["Ho descritto i tre tipi","Ho indicato la prevalenza della norma C"]},{"q":"Che cosa cambia per il costruttore con il nuovo regolamento?","min":6,"modello":"Dal 20 gennaio 2027 si applica il regolamento (UE) 2023/1230: requisiti aggiornati, anche per software e sistemi autonomi, istruzioni anche in formato digitale e nuove procedure per alcune categorie di macchine. Il costruttore deve pianificare la transizione dei fascicoli tecnici.","criteri":["Ho indicato la data di applicazione","Ho citato almeno due novità"]}],"nar":"Nel laboratorio aiuti un costruttore a usare le norme tecniche per una cesoia: presunzione di conformità, norme di tipo A, B e C e novità del regolamento macchine. Confronta ogni risposta con la soluzione di riferimento.","rif":"Reg. (UE) 2023/1230 · Dir. 2006/42/CE · UNI EN ISO 12100","est":true,"ancora":"Normazione tecnica e principio di precauzione"},{"t":"testo","tit":"Il sistema delle fonti","rif":"Artt. 32, 35, 41 Cost. · art. 2087 c.c. · Direttiva 89/391/CEE · artt. 1-3 D.lgs. 81/2008","lead":"La tutela della salute e sicurezza si fonda su fonti costituzionali, europee, legislative e tecniche, ordinate gerarchicamente.","punti":["Costituzione: salute come diritto fondamentale (art. 32), tutela del lavoro (art. 35), limite di sicurezza all'iniziativa economica (art. 41)","Diritto dell'Unione: direttiva quadro 89/391/CEE e direttive particolari; regolamenti (REACH, CLP, Macchine 2023/1230, DPI 2016/425)","Art. 2087 c.c.: norma di chiusura del sistema","D.lgs. 81/2008: campo di applicazione universale (art. 3), definizioni (art. 2)","Fonti secondarie e tecniche: decreti attuativi, Accordi Stato-Regioni, norme UNI, EN, ISO, CEI, buone prassi e linee guida"],"nar":"Le fonti della prevenzione sono ordinate gerarchicamente. Al vertice la Costituzione; poi il diritto dell'Unione europea, con la direttiva quadro e regolamenti direttamente applicabili come REACH, CLP, il nuovo regolamento macchine e il regolamento DPI; quindi il codice civile, con la norma di chiusura dell'articolo duemilaottantasette, e il Testo unico, che si applica a tutti i settori e a tutte le tipologie di lavoratori. Completano il quadro i decreti attuativi, gli Accordi Stato-Regioni, le norme tecniche e le buone prassi.","p":1.6},{"foto":false,"t":"testo","tit":"Norme tecniche, buone prassi e interpelli","lead":"Accanto alle norme di legge, il D.lgs. 81/2008 attribuisce un ruolo preciso a norme tecniche, buone prassi, linee guida e risposte agli interpelli.","punti":["Norme tecniche (art. 2 lett. u): specifiche approvate da organismi di normazione","Buone prassi (lett. v): soluzioni validate dalla Commissione consultiva permanente","Linee guida (lett. z): atti di indirizzo elaborati da ministeri, Regioni, INAIL","Interpelli (art. 12): le risposte costituiscono criteri interpretativi per la vigilanza","Conformità alle norme tecniche: presunzione di rispetto dei requisiti quando la legge vi rinvia"],"appro":"Il D.L. 159/2025 ha previsto un Bollettino ufficiale delle norme tecniche per agevolarne la conoscenza; l’attuazione dipende dai provvedimenti applicativi.","rif":"D.lgs. 81/2008, artt. 2, 6 e 12 · D.L. 159/2025, conv. L. 198/2025","nar":"Chi decide in materia di sicurezza non può fermarsi alla lettera della legge. Il testo unico definisce, all’articolo due, altre fonti che orientano le scelte. Le norme tecniche sono specifiche approvate da organismi di normazione nazionali, europei o internazionali, come UNI, CEI, CEN e ISO; quando la legge vi rinvia, la loro applicazione fa presumere il rispetto dei requisiti. Le buone prassi sono soluzioni organizzative o procedurali coerenti con la normativa, adottate volontariamente e validate dalla Commissione consultiva permanente dell’articolo sei. Le linee guida sono atti di indirizzo elaborati da ministeri, Regioni, INAIL e altri enti, ad esempio sulla valutazione dello stress o sugli ambienti confinati. L’articolo dodici disciplina infine l’interpello: organismi associativi, enti pubblici e ordini professionali possono porre quesiti di ordine generale alla Commissione per gli interpelli, e le risposte costituiscono criteri interpretativi e direttivi per l’esercizio delle attività di vigilanza. Per l’azienda questo significa che una scelta conforme a una risposta di interpello o a una norma tecnica richiamata è difficilmente contestabile. Il decreto legge centocinquantanove del duemilaventicinque ha previsto anche un bollettino ufficiale delle norme tecniche, per agevolarne la conoscenza.","est":true,"ancora":"Il sistema delle fonti"},{"foto":false,"t":"laboratorio","tit":"Laboratorio · Usare interpelli e buone prassi","lead":"Un’associazione di categoria ti chiede supporto su un dubbio interpretativo diffuso tra le imprese associate.","dossier":[["Dubbio","se un certo addestramento debba essere ripetuto a ogni cambio di modello di attrezzatura"],["Imprese","circa 200 associate"],["Fonti disponibili","risposte a interpelli, buone prassi validate, linee guida"]],"compiti":[{"q":"Chi può presentare un interpello e su che cosa?","min":6,"modello":"Organismi associativi a rilevanza nazionale, enti pubblici nazionali, consigli nazionali degli ordini e collegi professionali, su questioni di ordine generale sull’applicazione della normativa. Una singola impresa non lo presenta direttamente.","criteri":["Ho indicato i soggetti legittimati","Ho indicato il carattere generale"]},{"q":"Che valore hanno risposte agli interpelli, buone prassi e linee guida?","min":6,"modello":"Le risposte agli interpelli costituiscono criteri interpretativi e direttivi per l’attività di vigilanza. Le buone prassi sono soluzioni validate dalla Commissione consultiva; le linee guida sono atti di indirizzo. Aiutano a dimostrare scelte coerenti.","criteri":["Ho indicato il valore delle risposte","Ho distinto buone prassi e linee guida"]},{"q":"Come formuli il quesito?","min":6,"modello":"In modo generale e astratto, citando le norme interessate, descrivendo il dubbio senza riferimenti a singole aziende e proponendo, se utile, le interpretazioni possibili.","criteri":["Ho reso il quesito generale","Ho citato le norme"]}],"nar":"Nel laboratorio aiuti un’associazione di categoria a usare interpelli, buone prassi e linee guida: chi può presentare un interpello, valore delle fonti e formulazione del quesito. Confronta ogni risposta con la soluzione di riferimento.","rif":"Artt. 2, 6 e 12 D.lgs. 81/2008","est":true,"ancora":"Norme tecniche, buone prassi e interpelli"},{"foto":false,"t":"testo","tit":"Le radici della tutela: Costituzione e Codice civile","lead":"La tutela della salute nei luoghi di lavoro poggia su principi costituzionali e su una norma del Codice civile che resta il cardine dell’intero sistema.","punti":["Art. 32 Costituzione: la salute è fondamentale diritto dell’individuo e interesse della collettività","Art. 35 Costituzione: la Repubblica tutela il lavoro in tutte le sue forme","Art. 41 Costituzione: l’iniziativa economica non può svolgersi in modo da recare danno alla salute e alla sicurezza","Art. 2087 c.c.: l’imprenditore adotta le misure necessarie secondo la particolarità del lavoro, l’esperienza e la tecnica","Dal D.lgs. 626/1994 al D.lgs. 81/2008, il Testo unico vigente"],"appro":"L’art. 2087 c.c. è una norma «aperta»: obbliga a adottare anche misure non espressamente previste da leggi specifiche, se l’esperienza e la tecnica le rendono disponibili. Per questo la conformità formale ai singoli obblighi non esaurisce il dovere di sicurezza.","rif":"Costituzione, artt. 32, 35, 41 · Codice civile, art. 2087 · D.lgs. 81/2008","nar":"La tutela della salute e della sicurezza nei luoghi di lavoro poggia su principi di rango costituzionale. L’articolo trentadue della Costituzione riconosce la salute come fondamentale diritto dell’individuo e interesse della collettività. L’articolo trentacinque stabilisce che la Repubblica tutela il lavoro in tutte le sue forme e applicazioni. L’articolo quarantuno afferma che l’iniziativa economica privata è libera, ma non può svolgersi in modo da recare danno alla salute, alla sicurezza, alla libertà e alla dignità umana. Su queste basi si colloca una norma del Codice civile che resta il cardine dell’intero sistema: l’articolo duemilaottantasette, secondo il quale l’imprenditore è tenuto ad adottare le misure che, secondo la particolarità del lavoro, l’esperienza e la tecnica, sono necessarie a tutelare l’integrità fisica e la personalità morale dei prestatori di lavoro. Si tratta di una norma aperta: impone di adottare anche misure non previste da leggi specifiche, quando l’esperienza e la tecnica le rendono disponibili. La legislazione speciale si è sviluppata nel tempo, dal decreto legislativo seicentoventisei del millenovecentonovantaquattro fino al decreto legislativo ottantuno del duemilaotto, il testo unico oggi vigente, che riordina in un unico corpo le norme in materia.","est":true,"ancora":"Il sistema delle fonti"},{"foto":false,"t":"testo","tit":"Valutare tutti i rischi: genere, età, provenienza, tipologia contrattuale","lead":"La valutazione dei rischi deve riguardare tutti i rischi, compresi quelli che interessano gruppi di lavoratori esposti a rischi particolari.","punti":["Stress lavoro-correlato, secondo i contenuti dell’Accordo europeo dell’8 ottobre 2004","Lavoratrici in stato di gravidanza (D.lgs. 151/2001)","Differenze di genere, età e provenienza da altri Paesi","Specifica tipologia contrattuale con cui è resa la prestazione","Lavoratori in somministrazione, a termine, in lavoro agile: stessi diritti di tutela"],"appro":"Per i lavoratori stranieri l’informazione e la formazione devono essere comprensibili: l’art. 36 e l’art. 37 richiedono, se necessario, la verifica della comprensione della lingua utilizzata.","rif":"D.lgs. 81/2008, artt. 28, c. 1, 36, c. 4, e 37, c. 13 · D.lgs. 151/2001","nar":"L’articolo ventotto del testo unico stabilisce che la valutazione deve riguardare tutti i rischi per la sicurezza e la salute dei lavoratori, compresi quelli che interessano gruppi esposti a rischi particolari. La norma ne cita espressamente alcuni. Il primo è lo stress lavoro-correlato, da valutare secondo i contenuti dell’accordo europeo dell’otto ottobre duemilaquattro. Il secondo riguarda le lavoratrici in stato di gravidanza, per le quali si applicano anche le disposizioni del decreto legislativo centocinquantuno del duemilauno. La valutazione deve inoltre considerare le differenze di genere, l’età, la provenienza da altri Paesi e la specifica tipologia contrattuale con cui viene resa la prestazione. Un lavoratore somministrato, un lavoratore a termine o un lavoratore in modalità agile hanno diritto alla stessa tutela dei colleghi, e la valutazione deve tenere conto delle loro condizioni concrete, ad esempio la minore esperienza nel contesto aziendale. Per i lavoratori stranieri, informazione e formazione devono essere effettivamente comprensibili: il testo unico richiede, quando necessario, la verifica della comprensione della lingua utilizzata nel percorso formativo.","est":true,"ancora":"Il sistema delle fonti"},{"foto":false,"t":"laboratorio","tit":"Laboratorio · La valutazione per gruppi di lavoratori","lead":"Integri la valutazione dei rischi di un’impresa di servizi di pulizia con 80 addetti.","dossier":[["Composizione","70% donne; 25% sopra i 55 anni; 40% di provenienza estera; molti contratti part-time e a termine"],["Attività","pulizie in uffici e ospedali, anche in orari serali"],["Dati","disturbi muscolo-scheletrici frequenti; due aggressioni verbali in ospedale"]],"compiti":[{"q":"Quali rischi assumono rilievo per genere ed età?","min":7,"modello":"Movimentazione e posture con attrezzi non adattati alle caratteristiche fisiche; tutela della maternità e agenti chimici dei detergenti; affaticamento e recupero per i lavoratori più anziani; lavoro serale in solitudine.","criteri":["Ho considerato genere e maternità","Ho considerato l’età","Ho considerato il lavoro in solitudine"]},{"q":"Quali rischi per provenienza e tipologia contrattuale?","min":7,"modello":"Comprensione della lingua per istruzioni e schede dei prodotti; minore esperienza e formazione dei contratti brevi; continuità della sorveglianza sanitaria; minore propensione a segnalare problemi.","criteri":["Ho considerato la lingua","Ho considerato i contratti brevi"]},{"q":"Proponi misure specifiche.","min":7,"modello":"Attrezzi ergonomici regolabili e carrelli leggeri; schede di sicurezza e istruzioni con pittogrammi e nelle lingue necessarie; formazione all’inizio di ogni contratto; procedure per il lavoro serale e contro le aggressioni in accordo con il committente ospedaliero; canali di segnalazione semplici.","criteri":["Ho proposto misure per ogni gruppo","Ho coinvolto il committente"]}],"nar":"Nel laboratorio integri la valutazione dei rischi di un’impresa di pulizie considerando genere, età, provenienza e tipologia contrattuale, e proponi misure specifiche. Confronta ogni risposta con la soluzione di riferimento.","rif":"Art. 28, c. 1, D.lgs. 81/2008","est":true,"ancora":"Valutare tutti i rischi: genere, età, provenienza, tipologia contrattuale"},{"t":"definizioni","tit":"Le definizioni fondamentali","sott":"Art. 2 D.lgs. 81/2008 · Consultare tutte le schede","voci":[["a","Lavoratore","Persona che, indipendentemente dalla tipologia contrattuale, svolge un'attività lavorativa nell'ambito dell'organizzazione di un datore di lavoro pubblico o privato, con o senza retribuzione."],["n","Prevenzione","Complesso delle disposizioni o misure necessarie, anche secondo la particolarità del lavoro, l'esperienza e la tecnica, per evitare o diminuire i rischi professionali."],["o","Salute","Stato di completo benessere fisico, mentale e sociale, non consistente solo in un'assenza di malattia o d'infermità."],["r","Pericolo","Proprietà o qualità intrinseca di un determinato fattore avente il potenziale di causare danni."],["s","Rischio","Probabilità di raggiungimento del livello potenziale di danno nelle condizioni di impiego o di esposizione."],["q","Valutazione dei rischi","Valutazione globale e documentata di tutti i rischi per la salute e sicurezza, finalizzata a individuare le misure e a elaborare il programma di miglioramento."]],"nar":"Le definizioni dell'articolo due costituiscono il lessico del prevenzionista. Il lavoratore è chiunque operi nell'organizzazione, indipendentemente dal contratto. La salute è uno stato di completo benessere fisico, mentale e sociale. Il pericolo è una proprietà intrinseca, il rischio una probabilità. La valutazione dei rischi è globale e documentata, e serve a individuare le misure e il programma di miglioramento.","p":1.6},{"foto":false,"t":"classifica","tit":"Quale definizione?","lead":"Seleziona una descrizione, poi il termine definito dall’art. 2.","colonne":["Pericolo","Rischio","Prevenzione","Salute"],"schede":[["Proprietà o qualità intrinseca di un fattore con il potenziale di causare danni",0,"È il pericolo.","Corretto."],["Probabilità di raggiungimento del livello potenziale di danno nelle condizioni di impiego o di esposizione",1,"È il rischio.","Corretto."],["Complesso delle disposizioni o misure necessarie per evitare o diminuire i rischi professionali",2,"È la prevenzione.","Corretto."],["Stato di completo benessere fisico, mentale e sociale",3,"È la salute.","Corretto."],["Un solvente infiammabile in magazzino",0,"È un pericolo.","Corretto."],["La possibilità che il solvente prenda fuoco durante un travaso senza messa a terra",1,"È un rischio.","Corretto."]],"nar":"Sei descrizioni ed esempi. Associa ciascuno al termine definito dal Testo unico.","rif":"Art. 2 D.lgs. 81/2008","est":true,"ancora":"Le definizioni fondamentali"},{"t":"articolo","tit":"Le misure generali di tutela","art":"Art. 15, c. 1 D.lgs. 81/2008 (selezione)","commi":[["a","Valutazione di tutti i rischi"],["b","Programmazione della prevenzione, integrando condizioni tecniche e organizzative e l'influenza dei fattori dell'ambiente"],["c","Eliminazione dei rischi o, ove non possibile, loro riduzione al minimo secondo il progresso tecnico"],["d","Rispetto dei principi ergonomici"],["e","Riduzione dei rischi alla fonte"],["f","Sostituzione di ciò che è pericoloso con ciò che non lo è o lo è meno"],["g","Limitazione al minimo del numero di lavoratori esposti"],["i","Priorità delle misure collettive su quelle individuali"],["l","Controllo sanitario dei lavoratori"],["n","Informazione e formazione adeguate"],["r","Partecipazione e consultazione dei lavoratori"],["t","Programma delle misure per il miglioramento nel tempo"]],"nar":"L'articolo quindici è la sintesi dell'approccio preventivo: valutare tutti i rischi, programmare, eliminare o ridurre alla fonte, sostituire ciò che è pericoloso, ridurre il numero degli esposti, privilegiare la protezione collettiva, controllare la salute, informare, formare, consultare e migliorare nel tempo. Il consulente del datore di lavoro, cioè l'RSPP, ragiona sempre secondo questa gerarchia.","p":2},{"foto":false,"t":"laboratorio","tit":"Laboratorio · Le misure generali di tutela applicate","lead":"Applichi le misure generali di tutela dell’art. 15 a un reparto di sabbiatura.","dossier":[["Reparto","sabbiatura manuale di pezzi metallici in cabina"],["Problemi","polveri, rumore 92 dB(A), lavoratori a turni lunghi, manutenzione della cabina irregolare"]],"compiti":[{"q":"Applica la gerarchia: eliminazione, riduzione alla fonte, protezione collettiva, DPI.","min":7,"modello":"Eliminare o ridurre: valutare processi alternativi o abrasivi meno pericolosi e automazione. Alla fonte: cabina chiusa con aspirazione efficiente e insonorizzazione. Collettive: separazione del reparto, ventilazione. Solo infine DPI: protezione respiratoria adeguata e otoprotettori.","criteri":["Ho seguito l’ordine della gerarchia","Ho previsto misure alla fonte","Ho messo i DPI per ultimi"],"minc":120},{"q":"Quali misure organizzative e di salute aggiungi?","min":6,"modello":"Riduzione della durata di esposizione e rotazione; manutenzione programmata della cabina e dei filtri; sorveglianza sanitaria per polveri e rumore; informazione, formazione e addestramento; segnaletica e accesso limitato.","criteri":["Ho previsto organizzazione e manutenzione","Ho previsto sorveglianza sanitaria","Ho previsto formazione"]},{"q":"Come programmi il miglioramento nel tempo?","min":5,"modello":"Programma delle misure nel DVR con priorità, responsabili, risorse e scadenze; verifica dell’efficacia con nuove misure di rumore e polveri; riesame annuale.","criteri":["Ho previsto il programma","Ho previsto la verifica di efficacia"]}],"nar":"Nel laboratorio applichi le misure generali di tutela a un reparto di sabbiatura, seguendo la gerarchia e aggiungendo misure organizzative e di salute, poi programmi il miglioramento. Confronta ogni risposta con la soluzione di riferimento.","rif":"Art. 15 D.lgs. 81/2008","est":true,"ancora":"Le misure generali di tutela"},{"t":"confronto","tit":"Responsabilità civile e penale","rif":"Artt. 55-60 D.lgs. 81/2008 · artt. 40, 43, 589, 590 c.p. · art. 2087 c.c. · D.P.R. 1124/1965","sx":{"ico":"FaGavel","tit":"Responsabilità penale","voci":["Contravvenzioni del D.lgs. 81/2008 a carico di datore di lavoro, dirigenti, preposti, lavoratori, medico competente","Delitti di omicidio e lesioni colposi aggravati dalla violazione delle norme antinfortunistiche","Causalità omissiva (art. 40, c. 2 c.p.): non impedire un evento che si ha l'obbligo giuridico di impedire equivale a cagionarlo","L'RSPP non ha poteri decisionali, ma può rispondere in concorso per errori di valutazione o omesse segnalazioni"]},"dx":{"ico":"FaScaleBalanced","tit":"Responsabilità civile","voci":["Responsabilità contrattuale del datore di lavoro (art. 2087 c.c.)","Assicurazione obbligatoria INAIL (D.P.R. 1124/1965)","Danno differenziale e danno complementare risarcibili","Azione di regresso dell'INAIL in caso di reato"]},"nar":"Le responsabilità sono di natura penale e civile. In sede penale rispondono i titolari delle posizioni di garanzia per le contravvenzioni previste dal decreto e, in caso di infortunio, per omicidio o lesioni colposi. Particolare rilievo assume la causalità omissiva: non impedire un evento che si ha l'obbligo giuridico di impedire equivale a cagionarlo. L'RSPP è un consulente privo di poteri decisionali, ma la giurisprudenza ne riconosce la responsabilità in concorso quando un errore di valutazione o un'omessa segnalazione hanno contribuito all'evento. In sede civile il datore di lavoro risponde ai sensi dell'articolo duemilaottantasette, accanto alla tutela assicurativa INAIL.","p":1.8},{"foto":false,"t":"testo","tit":"Infortunio e responsabilità civile: esonero, regresso e danno differenziale","lead":"L’assicurazione INAIL esonera in parte il datore di lavoro dalla responsabilità civile, ma non quando il fatto costituisce reato.","punti":["Art. 10 D.P.R. 1124/1965: esonero dalla responsabilità civile per i danni indennizzati dall’INAIL","L’esonero non opera se il datore di lavoro è responsabile penalmente del fatto","Art. 11: azione di regresso dell’INAIL per le somme pagate al lavoratore","Danno differenziale: la parte del danno non coperta dall’indennizzo INAIL","Art. 2087 c.c.: obbligo di adottare le misure suggerite da particolarità del lavoro, esperienza e tecnica"],"appro":"In caso di infortunio con violazione di norme di sicurezza, ai costi penali si sommano il regresso INAIL e il risarcimento del danno differenziale.","rif":"D.P.R. 30 giugno 1965, n. 1124, artt. 10 e 11 · Codice civile, art. 2087","nar":"Quando un lavoratore subisce un infortunio, interviene l’assicurazione obbligatoria gestita dall’INAIL, che eroga le prestazioni economiche e sanitarie. L’articolo dieci del testo unico del millenovecentosessantacinque prevede che l’assicurazione esoneri il datore di lavoro dalla responsabilità civile per i danni indennizzati. L’esonero però non opera quando il datore di lavoro, o chi è preposto alla direzione e sorveglianza del lavoro, è riconosciuto responsabile penalmente del fatto, ad esempio per lesioni colpose commesse con violazione delle norme di sicurezza. In questo caso l’articolo undici consente all’INAIL di agire in regresso contro il datore di lavoro per recuperare le somme pagate al lavoratore. Inoltre il lavoratore può chiedere il risarcimento del cosiddetto danno differenziale, cioè della parte del danno non coperta dall’indennizzo, come alcune componenti del danno biologico e il danno morale. Il fondamento della responsabilità civile è l’articolo duemilaottantasette del codice civile, che impone all’imprenditore di adottare le misure che, secondo la particolarità del lavoro, l’esperienza e la tecnica, sono necessarie a tutelare l’integrità fisica e la personalità morale dei lavoratori. Per l’azienda, un infortunio con violazioni comporta quindi costi penali, il regresso e il risarcimento del danno differenziale.","est":true,"ancora":"Responsabilità civile e penale"},{"foto":false,"t":"laboratorio","tit":"Laboratorio · Le conseguenze di un infortunio","lead":"Ricostruisci le conseguenze giuridiche di una caduta dall’alto in un’impresa di installazione di impianti.","dossier":[["Evento","un tecnico cade da una copertura non protetta; prognosi di 70 giorni"],["Misure","nessun parapetto né linea vita; il tecnico non aveva l’imbracatura"],["Impresa","40 dipendenti, nessun modello organizzativo"]],"compiti":[{"q":"Quali conseguenze penali per le persone fisiche?","min":7,"modello":"Lesioni personali colpose gravi, perché la malattia supera i 40 giorni, aggravate dalla violazione delle norme di sicurezza, procedibili d’ufficio; possibili contravvenzioni del D.lgs. 81/2008 per l’omessa adozione delle misure contro le cadute.","criteri":["Ho indicato le lesioni gravi","Ho indicato le contravvenzioni"]},{"q":"Quali conseguenze civili e assicurative?","min":7,"modello":"L’INAIL indennizza il lavoratore; il datore di lavoro responsabile penalmente non beneficia dell’esonero e può subire il regresso dell’INAIL e la richiesta del danno differenziale.","criteri":["Ho indicato l’indennizzo INAIL","Ho indicato regresso e danno differenziale"]},{"q":"E per l’impresa come ente?","min":6,"modello":"Le lesioni gravi con violazione delle norme di sicurezza sono reato presupposto dell’art. 25-septies: senza modello organizzativo efficace l’ente rischia sanzioni pecuniarie e interdittive se c’è interesse o vantaggio, come il risparmio sulle protezioni.","criteri":["Ho collegato l’art. 25-septies","Ho indicato interesse o vantaggio"]}],"nar":"Nel laboratorio ricostruisci le conseguenze penali, civili e per l’ente di una caduta dall’alto. Confronta ogni risposta con la soluzione di riferimento.","rif":"Art. 590 c.p. · artt. 10-11 D.P.R. 1124/1965 · art. 25-septies D.lgs. 231/2001","est":true,"ancora":"Responsabilità civile e penale"},{"foto":false,"t":"esempio","tit":"Esempio guidato · Il danno differenziale","lead":"Che cosa resta a carico del datore di lavoro responsabile.","passi":[["L’evento","Un infortunio con postumi permanenti, di cui il datore di lavoro è riconosciuto responsabile penalmente.","Responsabilità accertata"],["Il danno civilistico","Il giudice liquida il danno complessivo secondo i criteri civilistici: ad esempio 120.000 €.","120.000 €"],["L’indennizzo INAIL","L’INAIL ha indennizzato il danno biologico e patrimoniale nei limiti della sua tutela: ad esempio 70.000 €.","70.000 €"],["Il differenziale","La differenza resta a carico del responsabile: 120.000 − 70.000 = 50.000 €.","50.000 €"],["Il regresso","L’INAIL può agire in regresso per recuperare quanto ha erogato.","Fino a 70.000 € di regresso"]],"nar":"Vediamo il danno differenziale con importi illustrativi. Il giudice liquida un danno complessivo di centoventimila euro; l’INAIL ha già indennizzato settantamila euro. La differenza, cinquantamila euro, resta a carico del datore di lavoro responsabile, e l’INAIL può agire in regresso per recuperare quanto ha pagato. L’esonero dalla responsabilità civile non opera quando c’è responsabilità penale.","rif":"Artt. 10 e 11 D.P.R. 1124/1965","est":true,"ancora":"Infortunio e responsabilità civile: esonero, regresso e danno differenziale"},{"foto":false,"t":"testo","tit":"Quando risponde l’RSPP","lead":"L’RSPP è consulente del datore di lavoro e non titolare di obblighi sanzionati, ma può concorrere nel reato colposo se il suo errore ha causato l’evento.","punti":["Nessuna sanzione contravvenzionale propria nel D.lgs. 81/2008 per l’RSPP","Responsabilità per omicidio o lesioni colpose in concorso, se l’errore consulenziale ha contribuito all’evento","Esempi: rischio non individuato, misura errata suggerita, mancata segnalazione di un pericolo noto","Il datore di lavoro resta responsabile delle scelte, anche se basate sul parere dell’RSPP","Tutela: documentare valutazioni, proposte e segnalazioni inviate al datore di lavoro"],"appro":"La giurisprudenza di legittimità afferma costantemente che l’RSPP risponde quando l’evento è riconducibile a una situazione pericolosa che avrebbe dovuto conoscere e segnalare.","rif":"D.lgs. 81/2008, artt. 31-33 · Codice penale, artt. 40, 41, 113, 589 e 590","nar":"Il responsabile del servizio di prevenzione e protezione svolge una funzione consultiva: individua i rischi, elabora le misure e le procedure, propone i programmi di formazione, partecipa alla riunione periodica. Per questo il testo unico non prevede sanzioni contravvenzionali a suo carico per l’inadempimento dei propri compiti. Ciò non significa che l’RSPP non possa essere chiamato a rispondere penalmente. La giurisprudenza di legittimità afferma costantemente che, in caso di infortunio, l’RSPP può concorrere nel delitto di omicidio colposo o di lesioni colpose quando l’evento è riconducibile a una situazione pericolosa che egli avrebbe dovuto conoscere e segnalare, oppure a un consiglio tecnico errato. Gli esempi tipici sono un rischio non individuato nella valutazione, una misura di prevenzione inadeguata suggerita al datore di lavoro, la mancata segnalazione di un pericolo noto. Il datore di lavoro resta comunque responsabile delle proprie scelte, anche se fondate sul parere del consulente. Per l’RSPP la tutela migliore è la tracciabilità del proprio lavoro: valutazioni motivate, proposte scritte con priorità e scadenze, segnalazioni documentate delle criticità rilevate nei sopralluoghi e dei ritardi nell’attuazione delle misure.","est":true,"ancora":"Responsabilità civile e penale"},{"foto":false,"t":"laboratorio","tit":"Laboratorio · L’RSPP e l’infortunio","lead":"Sei chiamato ad analizzare la posizione dell’RSPP esterno dopo un infortunio in un’officina.","dossier":[["Evento","un operaio si amputa una falange su un tornio parallelo privo di schermo paratrucioli interbloccato"],["DVR","redatto dall’RSPP due anni prima; il tornio è valutato «rischio basso» senza motivazione"],["Sopralluoghi","l’RSPP ha svolto due sopralluoghi annuali; nei verbali il tornio non è citato"],["Datore di lavoro","dichiara che avrebbe installato lo schermo se gli fosse stato segnalato"]],"compiti":[{"q":"L’RSPP ha sanzioni contravvenzionali proprie? Di che cosa può rispondere?","min":6,"modello":"No: il D.lgs. 81/2008 non prevede contravvenzioni proprie per l’RSPP. Può rispondere di lesioni colpose in concorso con il datore di lavoro, se un errore di valutazione o un’omessa segnalazione ha contribuito all’evento.","criteri":["Ho escluso le contravvenzioni proprie","Ho indicato il concorso nelle lesioni colpose"]},{"q":"Quali elementi del caso pesano contro l’RSPP?","min":8,"modello":"La valutazione «rischio basso» senza motivazione per una macchina con organi in movimento non protetti; l’assenza del tornio nei verbali dei sopralluoghi; la mancanza di segnalazioni scritte. La dichiarazione del datore di lavoro sostiene il nesso causale: con la segnalazione la misura sarebbe stata adottata.","criteri":["Ho individuato l’errore di valutazione","Ho individuato l’omessa segnalazione","Ho collegato il nesso causale"],"minc":120},{"q":"Quali elementi potrebbero invece tutelarlo?","min":6,"modello":"Una segnalazione scritta del rischio precedente all’evento; proposte di misure documentate e rimaste inattuate per decisione del datore di lavoro; verbali di sopralluogo dettagliati. In assenza di questi documenti la difesa è debole.","criteri":["Ho indicato le segnalazioni scritte","Ho indicato le proposte documentate"]},{"q":"Scrivi tre regole di lavoro che un RSPP dovrebbe seguire per tutelarsi.","min":8,"modello":"Motivare ogni valutazione con criteri espliciti e dati; segnalare per iscritto, con data, ogni rischio rilevato e la misura proposta, chiedendo un riscontro; registrare i sopralluoghi con le macchine e le aree visitate e seguire nel tempo lo stato delle proposte.","criteri":["Ho previsto valutazioni motivate","Ho previsto segnalazioni scritte con riscontro","Ho previsto il monitoraggio delle proposte"],"minc":120}],"nar":"Nel laboratorio analizzi la posizione di un RSPP dopo un infortunio su un tornio. Stabilisci di che cosa può rispondere, quali elementi pesano contro di lui e quali lo tutelerebbero, poi scrivi tre regole di lavoro. Confronta ogni risposta con la soluzione di riferimento.","rif":"Artt. 31-33 D.lgs. 81/2008 · Cass. pen., Sezioni Unite, n. 38343/2014","est":true,"ancora":"Quando risponde l’RSPP"},{"t":"testo","tit":"La responsabilità amministrativa degli enti","rif":"Art. 25-septies D.lgs. 231/2001 · art. 30 D.lgs. 81/2008 · UNI EN ISO 45001","lead":"Per omicidio colposo e lesioni gravi o gravissime commessi con violazione delle norme antinfortunistiche, nell'interesse o a vantaggio dell'ente, risponde anche l'ente.","punti":["Sanzioni pecuniarie fino a 1.000 quote e sanzioni interdittive","Interesse o vantaggio: anche il risparmio di costi o di tempi","Esimente: modello di organizzazione e gestione adottato ed efficacemente attuato, con organismo di vigilanza e sistema disciplinare","Art. 30 D.lgs. 81/2008: requisiti del modello; presunzione di conformità per i modelli conformi alla UNI EN ISO 45001","Il servizio di prevenzione contribuisce alla costruzione e all'attuazione del modello"],"nar":"Il decreto duecentotrentuno del duemilauno estende la responsabilità all'ente per l'omicidio e le lesioni gravi colposi commessi nel suo interesse o a suo vantaggio, anche solo come risparmio di costi. L'ente evita la sanzione se ha adottato ed efficacemente attuato un modello di organizzazione e gestione conforme all'articolo trenta, con organismo di vigilanza e sistema disciplinare. Il servizio di prevenzione è protagonista nella costruzione del modello.","p":1.5},{"foto":false,"t":"scenario","tit":"L’interesse dell’ente","scena":"Per rispettare una consegna, il direttore di produzione autorizza a lavorare con una pressa senza la barriera fotoelettrica, guasta da giorni. Un operaio si ferisce gravemente.","decisioni":[{"dom":"C’è interesse o vantaggio dell’ente?","opz":[["Sì: il risparmio di tempo e il rispetto della consegna sono un vantaggio per l’ente",true,"Corretto: anche il risparmio di tempi o costi integra il criterio."],["No, l’ente non voleva l’infortunio",false,"Non serve volere l’evento."],["Solo se c’è un guadagno in denaro",false,"Basta il risparmio di tempi."]]},{"dom":"Quale reato presupposto può essere contestato?","opz":[["Lesioni colpose gravi con violazione delle norme di sicurezza, art. 25-septies",true,"Corretto."],["Truffa",false,"Non pertinente."],["Nessuno",false,"È un reato presupposto."]]},{"dom":"Che cosa avrebbe tutelato l’ente?","opz":[["Un modello organizzativo efficace con procedure di blocco delle macchine guaste, vigilanza e sistema disciplinare",true,"Corretto."],["Una polizza",false,"Non esclude la responsabilità."],["Un cartello",false,"Non basta."]]}],"chiusura":"Anche un risparmio di tempo è un vantaggio per l’ente: senza un modello efficace, una lesione grave da violazione delle norme di sicurezza coinvolge l’impresa.","nar":"Una pressa usata senza barriera per rispettare una consegna. Valuta la responsabilità dell’ente.","rif":"D.lgs. 231/2001, artt. 5 e 25-septies","est":true,"ancora":"La responsabilità amministrativa degli enti"},{"t":"testo","tit":"La responsabilità dell’ente: art. 25-septies D.lgs. 231/2001","foto":false,"lead":"Per l’omicidio colposo e le lesioni colpose gravi o gravissime commessi con violazione delle norme di sicurezza risponde anche l’ente, se il reato è commesso nel suo interesse o a suo vantaggio.","punti":["Omicidio colposo con violazione dell’art. 55, c. 2 (aziende a rischio particolare): sanzione pecuniaria pari a 1.000 quote","Altri casi di omicidio colposo: sanzione da 250 a 500 quote; lesioni gravi o gravissime: fino a 250 quote","Sanzioni interdittive: per l’omicidio colposo da 3 mesi a 1 anno; per le lesioni non superiori a 6 mesi","Interesse o vantaggio: nei reati colposi si identificano nel risparmio di costi o di tempi derivante dalla mancata adozione delle misure","Esimente: adozione ed efficace attuazione, prima del fatto, di un modello di organizzazione e gestione idoneo (art. 30 D.lgs. 81/2008)"],"appro":"Il valore di una quota va da circa 258 a 1.549 euro: la sanzione massima per l’omicidio colposo aggravato può superare 1,5 milioni di euro, oltre alla confisca del profitto e alla pubblicazione della sentenza. Il modello organizzativo è idoneo se assicura l’adempimento di tutti gli obblighi elencati nell’art. 30, c. 1, prevede sistemi di registrazione, un’articolazione di funzioni, un sistema disciplinare e un idoneo sistema di controllo.","rif":"Art. 25-septies e artt. 9-11 D.lgs. 231/2001 · art. 30 D.lgs. 81/2008","nar":"Quando un infortunio grave o mortale deriva dalla violazione delle norme di sicurezza, risponde anche la società, se il reato le ha procurato un interesse o un vantaggio, ad esempio un risparmio sui costi della sicurezza. Per l’omicidio colposo nelle aziende a rischio particolare la sanzione arriva a mille quote, oltre alle sanzioni interdittive. La società si difende dimostrando di aver adottato ed efficacemente attuato, prima del fatto, un modello organizzativo idoneo.","p":1.5},{"foto":false,"t":"testo","tit":"Il modello organizzativo dell’art. 30","lead":"L’art. 30 del D.lgs. 81/2008 indica i contenuti del modello di organizzazione e gestione idoneo ad avere efficacia esimente per l’ente.","punti":["Rispetto degli standard tecnico-strutturali per attrezzature, impianti, luoghi, agenti","Valutazione dei rischi, emergenze, appalti, riunioni periodiche, consultazione","Sorveglianza sanitaria, informazione e formazione, vigilanza sulle procedure","Registrazione delle attività, articolazione di funzioni e sistema disciplinare","Presunzione di conformità per i modelli basati su UNI-INAIL 2001 o BS OHSAS 18001 (oggi ISO 45001)"],"appro":"Per le piccole e medie imprese il D.M. 13 febbraio 2014 ha approvato procedure semplificate per l’adozione del modello (art. 30 c. 5-bis).","rif":"D.lgs. 81/2008, art. 30 · D.lgs. 231/2001, artt. 6, 7 e 25-septies · D.M. 13 febbraio 2014","nar":"L’articolo venticinque septies del decreto duecentotrentuno del duemilauno rende l’ente responsabile per l’omicidio colposo e le lesioni gravi o gravissime commessi con violazione delle norme sulla sicurezza nel suo interesse o a suo vantaggio, anche come risparmio di costi o di tempi. L’ente può andare esente se ha adottato ed efficacemente attuato un modello di organizzazione e gestione idoneo. L’articolo trenta del testo unico ne indica i contenuti: il modello deve assicurare il rispetto degli standard tecnico strutturali di legge per attrezzature, impianti, luoghi di lavoro e agenti; la valutazione dei rischi e le conseguenti misure; la gestione delle emergenze, degli appalti, delle riunioni periodiche e della consultazione; la sorveglianza sanitaria; l’informazione e la formazione; la vigilanza sul rispetto delle procedure; l’acquisizione delle documentazioni obbligatorie e le verifiche periodiche. Il modello prevede sistemi di registrazione, un’articolazione di funzioni con competenze e poteri adeguati, un sistema disciplinare e un sistema di controllo sull’attuazione, con riesame quando emergono violazioni o cambiamenti. In sede di prima applicazione si presumono conformi i modelli basati sulle linee guida UNI INAIL o sullo standard britannico oggi sostituito dalla ISO quarantacinquemilauno. Per le piccole e medie imprese sono previste procedure semplificate.","est":true,"ancora":"La responsabilità dell’ente: art. 25-septies D.lgs. 231/2001"},{"foto":false,"t":"laboratorio","tit":"Laboratorio · Il modello organizzativo per una PMI","lead":"Imposti il modello di organizzazione e gestione dell’art. 30 per una PMI metalmeccanica di 45 lavoratori.","dossier":[["Situazione","DVR aggiornato, nessun sistema di gestione certificato"],["Obiettivo","efficacia esimente ai sensi del D.lgs. 231/2001"],["Risorse","RSPP esterno, un responsabile qualità interno"]],"compiti":[{"q":"Quali obblighi giuridici deve presidiare il modello?","min":7,"modello":"Standard tecnico-strutturali di attrezzature, impianti, luoghi e agenti; valutazione dei rischi e misure; emergenze, primo soccorso, appalti, riunioni periodiche, consultazione; sorveglianza sanitaria; informazione e formazione; vigilanza sul rispetto delle procedure; documentazione e certificazioni obbligatorie; verifiche periodiche.","criteri":["Ho elencato gli ambiti dell’art. 30, comma 1","Ho incluso la vigilanza"],"minc":100},{"q":"Quali elementi organizzativi aggiungi?","min":7,"modello":"Sistemi di registrazione delle attività; articolazione di funzioni con competenze e poteri; sistema disciplinare per il mancato rispetto delle misure; sistema di controllo sull’attuazione e sul mantenimento del modello; riesame e modifica in caso di violazioni o cambiamenti.","criteri":["Ho previsto registrazioni e funzioni","Ho previsto il sistema disciplinare","Ho previsto controllo e riesame"]},{"q":"Che cosa prevede la legge per le PMI e per i modelli conformi alle norme?","min":6,"modello":"In sede di prima applicazione i modelli conformi alla UNI EN ISO 45001 si presumono conformi per le parti corrispondenti; per le piccole e medie imprese sono previste procedure semplificate. Il D.L. 159/2025 ha aggiornato il riferimento alla UNI EN ISO 45001.","criteri":["Ho citato la presunzione di conformità","Ho citato le procedure semplificate per le PMI"]},{"q":"Proponi un piano di attuazione in sei mesi.","min":7,"modello":"Mese 1: analisi delle attività sensibili e dei controlli esistenti. Mesi 2-3: procedure, deleghe, registrazioni e sistema disciplinare. Mese 4: formazione e comunicazione. Mese 5: organismo di vigilanza e flussi informativi. Mese 6: primo audit interno e riesame della direzione.","criteri":["Ho previsto l’analisi iniziale","Ho previsto procedure, formazione e organismo di vigilanza","Ho previsto audit e riesame"],"minc":120}],"nar":"Nel laboratorio imposti il modello organizzativo dell’articolo trenta per una PMI metalmeccanica: obblighi da presidiare, elementi organizzativi, semplificazioni per le PMI e un piano di attuazione. Confronta ogni risposta con la soluzione di riferimento.","rif":"Art. 30 D.lgs. 81/2008 · D.lgs. 231/2001","est":true,"ancora":"Il modello organizzativo dell’art. 30"},{"foto":false,"t":"testo","tit":"Le segnalazioni di illeciti: il D.lgs. 24/2023","lead":"Il D.lgs. 24/2023 sul whistleblowing disciplina canali di segnalazione, riservatezza e tutele per chi segnala violazioni, anche ambientali e di sicurezza.","punti":["Canali interni obbligatori per gli enti pubblici, le imprese con almeno 50 lavoratori e gli enti con modello 231","Gestore indipendente e formato; riservatezza dell’identità del segnalante","Avviso di ricevimento entro 7 giorni e riscontro entro 3 mesi","Canale esterno presso l’ANAC e divulgazione pubblica alle condizioni di legge","Divieto di ritorsioni e sanzioni ANAC per chi le attua o non istituisce i canali"],"appro":"Nel modello 231 il sistema di segnalazione è uno degli strumenti con cui l’organismo di vigilanza intercetta tempestivamente le violazioni, comprese quelle ambientali.","rif":"D.lgs. 10 marzo 2023, n. 24 · D.lgs. 231/2001, art. 6 c. 2-bis","nar":"Il decreto legislativo ventiquattro del duemilaventitré, che recepisce la direttiva europea sul whistleblowing, disciplina la protezione delle persone che segnalano violazioni di disposizioni nazionali o europee di cui sono venute a conoscenza nel contesto lavorativo. Rientrano tra le violazioni segnalabili anche quelle in materia di tutela dell’ambiente e, per gli enti dotati di modello organizzativo, le condotte rilevanti ai sensi del decreto duecentotrentuno. Gli enti pubblici, le imprese con almeno cinquanta lavoratori e gli enti che hanno adottato il modello organizzativo devono istituire canali interni di segnalazione, scritti e orali, affidati a un gestore autonomo e formato, che garantiscano la riservatezza dell’identità del segnalante, delle persone coinvolte e del contenuto. Il gestore rilascia un avviso di ricevimento entro sette giorni e fornisce un riscontro entro tre mesi. Alle condizioni previste dalla legge il segnalante può utilizzare il canale esterno dell’Autorità nazionale anticorruzione o ricorrere alla divulgazione pubblica. Sono vietate le ritorsioni, come licenziamenti, demansionamenti o trasferimenti, e l’Autorità può applicare sanzioni a chi le attua o a chi non istituisce i canali. Nel modello organizzativo il sistema di segnalazione è uno degli strumenti con cui l’organismo di vigilanza intercetta per tempo le violazioni, comprese quelle ambientali.","est":true,"ancora":"La responsabilità dell’ente: art. 25-septies D.lgs. 231/2001"},{"foto":false,"t":"scenario","tit":"La segnalazione del magazziniere","scena":"Un magazziniere nota che fusti di solvente esausto vengono caricati su un furgone senza formulario. Teme ritorsioni.","decisioni":[{"dom":"Che cosa può fare?","opz":[["Nulla: non è affar suo",false,"Il D.lgs. 24/2023 tutela chi segnala violazioni nel contesto lavorativo."],["Usare il canale di segnalazione interno dell’impresa",true,"Corretto: il canale interno garantisce la riservatezza dell’identità del segnalante."],["Pubblicare subito un video sui social",false,"La divulgazione pubblica è tutelata solo in condizioni specifiche, dopo i canali interni ed esterni o in caso di pericolo imminente."]]},{"dom":"Chi gestisce la segnalazione?","opz":[["Il responsabile del magazzino coinvolto",false,"Chi gestisce le segnalazioni deve essere autonomo e formato, non coinvolto nei fatti."],["Il gestore del canale individuato dall’impresa, che dà riscontro nei termini previsti",true,"Corretto: avviso di ricevimento entro 7 giorni e riscontro entro 3 mesi."],["Nessuno: le segnalazioni anonime si archiviano",false,"Le segnalazioni vanno gestite secondo la procedura."]]},{"dom":"Dopo la segnalazione il magazziniere viene trasferito a un turno sgradito. Che cosa prevede la legge?","opz":[["È una ritorsione vietata, che può essere comunicata all’ANAC",true,"Corretto: il D.lgs. 24/2023 vieta le ritorsioni e prevede sanzioni."],["È legittimo se deciso dal capo reparto",false,"Le misure ritorsive sono nulle."],["Il segnalante perde la tutela",false,"La tutela resta se la segnalazione è fatta in buona fede."]]}],"chiusura":"Canale interno, riservatezza, riscontro nei tempi e divieto di ritorsioni: sono le garanzie che rendono utile la segnalazione anche per prevenire reati ambientali.","nar":"Un lavoratore vede una gestione irregolare dei rifiuti. Accompagnalo nella segnalazione.","rif":"D.lgs. 24/2023","est":true,"ancora":"Le segnalazioni di illeciti: il D.lgs. 24/2023"},{"foto":false,"t":"esempio","tit":"Esempio guidato · La sanzione all’ente per un infortunio mortale","lead":"Il sistema per quote applicato all’art. 25-septies.","passi":[["Il reato","Omicidio colposo commesso con violazione dell’art. 55, comma 2, in un’azienda a rischio particolare.","Art. 25-septies, c. 1"],["Le quote","La sanzione è pari a 1.000 quote.","1.000 quote"],["Il valore della quota","Il giudice lo fissa tra 258 e 1.549 € secondo le condizioni economiche dell’ente: ad esempio 500 €.","500 € per quota"],["La sanzione pecuniaria","1.000 × 500 = 500.000 €.","500.000 €"],["Le interdittive","Si aggiungono sanzioni interdittive per una durata non inferiore a tre mesi e non superiore a un anno.","Da 3 mesi a 1 anno"]],"nar":"Vediamo la sanzione all’ente nel caso più grave. Per l’omicidio colposo commesso con violazione dell’articolo cinquantacinque, comma due, la sanzione è di mille quote. Se il giudice fissa la quota a cinquecento euro, la sanzione è di cinquecentomila euro, a cui si aggiungono sanzioni interdittive da tre mesi a un anno. Un modello organizzativo efficace è la principale difesa.","rif":"D.lgs. 231/2001, artt. 10, 11 e 25-septies","est":true,"ancora":"La responsabilità dell’ente: art. 25-septies D.lgs. 231/2001"},{"t":"caso","tit":"Esercitazione · Delega, budget e macchina non conforme","scena":"In uno stabilimento il direttore di produzione ha una delega in materia di sicurezza con autonomia di spesa fino a 20.000 euro. Una pressa priva di ripari interbloccati richiede un adeguamento da 35.000 euro. Il direttore chiede il budget a voce, non lo ottiene e lascia la macchina in funzione. Un operatore subisce un’amputazione.","domanda":"Come si ripartiscono le responsabilità?","opz":[["Risponde solo l’amministratore, che non ha concesso il budget",false,"No: il delegato aveva poteri e doveva adottare le misure possibili, compreso il fermo della macchina."],["Il delegato risponde perché poteva fermare la macchina o adottare misure provvisorie e doveva formalizzare la richiesta; il datore di lavoro risponde per l’omessa vigilanza sul delegato e per il mancato stanziamento; l’ente può rispondere ai sensi dell’art. 25-septies",true,"Corretto: la delega non elimina la vigilanza del delegante (art. 16, c. 3); il limite di spesa non giustifica l’uso di una macchina pericolosa."],["Risponde solo il lavoratore",false,"No: l’assenza di ripari rende l’evento pienamente riconducibile all’area di rischio governata dai garanti."]],"rif":"Artt. 16, 18, 71 D.lgs. 81/2008 · art. 25-septies D.lgs. 231/2001","appro":"Il risparmio sull’adeguamento costituisce il «vantaggio» dell’ente nei reati colposi: è l’ipotesi tipica della responsabilità amministrativa da reato in materia di sicurezza.","nar":"Esercitazione. Esaminato il caso proposto, si individui la risposta corretta, motivandola con i pertinenti riferimenti normativi.","p":1.3},{"t":"figure","tit":"Il sistema istituzionale della prevenzione","sott":"Artt. 5-14 D.lgs. 81/2008 · Consultare ciascuna voce","voci":[["FaLandmark","Comitato e Commissione consultiva","Comitato per l'indirizzo e la valutazione delle politiche (art. 5) e Commissione consultiva permanente (art. 6): buone prassi, linee guida, procedure standardizzate."],["FaMapLocationDot","Comitati regionali","Coordinamento delle attività di prevenzione e vigilanza sul territorio (art. 7)."],["FaShieldHalved","ASL e Ispettorato","Vigilanza (art. 13): ASL in via generale; Ispettorato nazionale del lavoro con competenza estesa dalla L. 215/2021."],["FaFireExtinguisher","Vigili del fuoco","Vigilanza in materia di prevenzione incendi."],["FaBuildingShield","INAIL","Assicurazione, ricerca, informazione, incentivi (bandi ISI), banche dati e sistema informativo (art. 8-9)."],["FaHandshake","Organismi paritetici","Supporto alle imprese, formazione, asseverazione dei modelli (art. 51)."]],"nar":"Il sistema istituzionale comprende gli organi di indirizzo e la Commissione consultiva, che approva buone prassi e procedure standardizzate; i comitati regionali di coordinamento; gli organi di vigilanza, cioè ASL, Ispettorato del lavoro e Vigili del fuoco; l'INAIL, che assicura, finanzia e gestisce il sistema informativo; gli organismi paritetici, che supportano le imprese e possono asseverare i modelli organizzativi.","p":1.6},{"foto":false,"t":"testo","tit":"Gli organismi nazionali e regionali della prevenzione","lead":"Gli artt. 5-9 del D.lgs. 81/2008 definiscono gli organismi che indirizzano, coordinano e sostengono la prevenzione.","punti":["Comitato per l’indirizzo e la valutazione delle politiche attive (art. 5)","Commissione consultiva permanente: buone prassi, procedure standardizzate, criteri (art. 6)","Comitati regionali di coordinamento: programmazione e coordinamento della vigilanza (art. 7)","Sistema informativo nazionale per la prevenzione, SINP (art. 8)","INAIL e altri enti pubblici: informazione, formazione, assistenza e ricerca (art. 9)"],"appro":"L’INAIL sostiene la prevenzione anche con incentivi economici: i bandi per progetti di miglioramento e la riduzione del tasso di premio per interventi migliorativi.","rif":"D.lgs. 81/2008, artt. 5-10","nar":"Il testo unico organizza la prevenzione su più livelli istituzionali. A livello nazionale, il Comitato per l’indirizzo e la valutazione delle politiche attive, previsto dall’articolo cinque, stabilisce le linee comuni delle politiche nazionali e individua obiettivi e programmi. La Commissione consultiva permanente dell’articolo sei esamina i problemi applicativi della normativa, valida le buone prassi, elabora le procedure standardizzate per la valutazione dei rischi e i criteri per le attività di vigilanza. A livello territoriale, i Comitati regionali di coordinamento dell’articolo sette programmano e coordinano le attività di prevenzione e vigilanza svolte da aziende sanitarie, Ispettorato, Vigili del fuoco e INAIL. L’articolo otto istituisce il Sistema informativo nazionale per la prevenzione, che raccoglie e integra i dati su infortuni, malattie professionali, esposizioni e attività di vigilanza, per orientare le politiche. L’articolo nove attribuisce all’INAIL e agli altri enti pubblici compiti di informazione, formazione, assistenza, consulenza e ricerca. L’INAIL sostiene la prevenzione anche con strumenti economici: i bandi per il finanziamento di progetti di miglioramento della sicurezza e la riduzione del tasso medio di premio per le aziende che hanno effettuato interventi migliorativi.","est":true,"ancora":"Il sistema istituzionale della prevenzione"},{"foto":false,"t":"scenario","tit":"A chi rivolgersi?","scena":"Un’impresa ha tre questioni: un dubbio interpretativo, una richiesta di contributo per un investimento in sicurezza e la verifica periodica di un apparecchio di sollevamento.","decisioni":[{"dom":"Per il contributo all’investimento?","opz":[["All’INAIL, tramite i bandi per gli investimenti in sicurezza",true,"Corretto."],["All’ASL",false,"Non eroga questi contributi."],["Ai Vigili del fuoco",false,"Non è la loro competenza."]]},{"dom":"Per la verifica periodica dell’apparecchio di sollevamento?","opz":[["All’INAIL per la prima verifica e all’ASL o a soggetti abilitati per le successive",true,"Corretto: art. 71, comma 11."],["Al costruttore",false,"Non esegue le verifiche periodiche di legge."],["A nessuno",false,"Le verifiche sono obbligatorie."]]},{"dom":"Per il dubbio interpretativo?","opz":[["Attraverso la propria associazione di categoria, che può presentare un interpello",true,"Corretto."],["Direttamente al Ministero, come singola impresa",false,"La singola impresa non è legittimata all’interpello."],["Al giudice",false,"Non è la sede."]]}],"chiusura":"Il sistema istituzionale ha compiti diversi: INAIL per incentivi e prime verifiche, ASL e soggetti abilitati per le verifiche successive, associazioni per gli interpelli.","nar":"Tre questioni da indirizzare all’ente giusto.","rif":"Artt. 9, 12 e 71 D.lgs. 81/2008","est":true,"ancora":"Il sistema istituzionale della prevenzione"},{"t":"processo","tit":"Vigilanza, prescrizione e sospensione","rif":"Artt. 13, 14, 301 D.lgs. 81/2008 · D.lgs. 758/1994","passi":[["Accesso","Gli ispettori, ufficiali di polizia giudiziaria, accedono ai luoghi di lavoro e acquisiscono documenti"],["Prescrizione","Per le contravvenzioni: prescrizione con termine per la regolarizzazione"],["Verifica","Accertamento dell'adempimento nei termini"],["Estinzione","Pagamento di un quarto del massimo dell'ammenda: il reato si estingue"],["Sospensione","Lavoro irregolare oltre il 10% o gravi violazioni dell'Allegato I: sospensione dell'attività (art. 14)"]],"nar":"La procedura di vigilanza prevede l'accesso degli ispettori, la prescrizione con un termine per regolarizzare, la verifica dell'adempimento e l'estinzione del reato con il pagamento di un quarto del massimo dell'ammenda. Per il lavoro irregolare oltre il dieci per cento o per le gravi violazioni dell'Allegato uno l'Ispettorato può sospendere l'attività.","p":1.5},{"t":"testo","tit":"L’ispezione: poteri degli organi di vigilanza e sospensione dell’attività","foto":false,"lead":"La vigilanza è svolta in via ordinaria dalle ASL; l’Ispettorato Nazionale del Lavoro ha competenza generale in materia di salute e sicurezza; i Vigili del fuoco per la prevenzione incendi (art. 13).","punti":["Poteri ispettivi: accesso ai luoghi di lavoro, esame dei documenti, assunzione di informazioni, prelievi e campionamenti","Il personale ispettivo ha qualifica di ufficiale di polizia giudiziaria: può disporre sequestri e trasmettere la notizia di reato","Sospensione dell’attività (art. 14): quando almeno il 10% dei lavoratori presenti risulta occupato senza preventiva comunicazione di instaurazione del rapporto, oppure per gravi violazioni elencate nell’Allegato I","Revoca della sospensione: regolarizzazione dei lavoratori, ripristino delle condizioni di sicurezza, pagamento della somma aggiuntiva","Durante l’ispezione: collaborazione, presenza del referente, verbale di quanto acquisito; le dichiarazioni rese possono essere utilizzate nel procedimento"],"appro":"L’Allegato I individua violazioni gravi come la mancata elaborazione del DVR, la mancata formazione e addestramento, la mancata costituzione del servizio di prevenzione, la mancanza di protezioni contro le cadute dall’alto, i lavori in prossimità di linee elettriche senza precauzioni, la mancanza di protezioni sulle parti in movimento delle macchine. La sospensione è un provvedimento cautelare e amministrativo, distinto dalle sanzioni penali.","rif":"Artt. 13, 14 e Allegato I D.lgs. 81/2008 · L. 215/2021","nar":"La vigilanza è svolta dalle ASL, dall’Ispettorato Nazionale del Lavoro e, per l’antincendio, dai Vigili del fuoco. Gli ispettori sono ufficiali di polizia giudiziaria: possono accedere ai luoghi, esaminare documenti, campionare e disporre sequestri. L’attività può essere sospesa quando almeno il dieci per cento dei lavoratori presenti è irregolare o per gravi violazioni di sicurezza, come la mancanza del DVR o della formazione. La sospensione si revoca regolarizzando e ripristinando le condizioni di sicurezza.","p":1.5},{"foto":false,"t":"testo","tit":"La prescrizione e l’estinzione delle contravvenzioni","lead":"Le contravvenzioni in materia di sicurezza possono estinguersi con la procedura del D.lgs. 758/1994, richiamata dall’art. 301 del D.lgs. 81/2008.","punti":["L’organo di vigilanza impartisce una prescrizione con un termine per regolarizzare","Il termine è prorogabile una sola volta, su richiesta motivata, per non oltre sei mesi","Verifica dell’adempimento entro 60 giorni dalla scadenza del termine","Ammissione al pagamento di un quarto del massimo dell’ammenda entro 30 giorni","Pagamento eseguito: il reato si estingue; in caso contrario prosegue il procedimento penale"],"appro":"Per gli illeciti amministrativi l’art. 301-bis consente l’estinzione con la regolarizzazione e il pagamento della sanzione in misura minima.","rif":"D.lgs. 19 dicembre 1994, n. 758, artt. 20-24 · D.lgs. 81/2008, artt. 301 e 301-bis","nar":"Gran parte delle violazioni del testo unico sono contravvenzioni punite con l’arresto o con l’ammenda. Per queste l’articolo trecentouno richiama la procedura di estinzione del decreto legislativo settecentocinquantotto del millenovecentonovantaquattro. Quando accerta una violazione, l’organo di vigilanza, nella sua veste di polizia giudiziaria, impartisce al contravventore una prescrizione, indicando le misure da adottare e un termine per la regolarizzazione, tecnicamente necessario. Il termine può essere prorogato una sola volta, su richiesta motivata, per un periodo non superiore a sei mesi. Entro sessanta giorni dalla scadenza l’organo verifica se la violazione è stata eliminata; in caso positivo ammette il contravventore a pagare, entro trenta giorni, una somma pari a un quarto del massimo dell’ammenda prevista. Con l’adempimento e il pagamento il reato si estingue. Se la prescrizione non viene rispettata o la somma non viene pagata, la notizia di reato prosegue il suo corso davanti al pubblico ministero. Per gli illeciti amministrativi l’articolo trecentouno bis consente invece l’estinzione con la regolarizzazione e il pagamento della sanzione nella misura minima. Per chi dirige l’azienda conta soprattutto il rispetto rigoroso del termine e la documentazione della regolarizzazione.","est":true,"ancora":"L’ispezione: poteri degli organi di vigilanza e sospensione dell’attività"},{"foto":false,"t":"esempio","tit":"Esempio guidato · Estinguere una contravvenzione","lead":"La procedura del D.lgs. 758/1994.","passi":[["La violazione","L’ispettore accerta che alcuni lavoratori non hanno ricevuto la formazione specifica.","Contravvenzione"],["La prescrizione","Termine di 60 giorni per completare la formazione, prorogabile una sola volta su richiesta motivata.","Adempiere nel termine"],["La verifica","Entro 60 giorni dalla scadenza l’organo di vigilanza verifica l’adempimento.","Verifica"],["Il pagamento","Il contravventore è ammesso a pagare un quarto del massimo dell’ammenda entro 30 giorni: con un massimo indicativo di 7.000 €, 1.750 €.","¼ del massimo"],["L’estinzione","Con adempimento e pagamento la contravvenzione si estingue.","Estinzione"]],"nar":"Seguiamo la procedura di estinzione. L’ispettore accerta che alcuni lavoratori non hanno la formazione specifica e prescrive di completarla entro sessanta giorni. Verificato l’adempimento, il contravventore paga un quarto del massimo dell’ammenda entro trenta giorni: con un massimo indicativo di settemila euro, sono millesettecentocinquanta euro. Così la contravvenzione si estingue.","rif":"D.lgs. 758/1994, artt. 20-24 · art. 301 D.lgs. 81/2008","est":true,"ancora":"La prescrizione e l’estinzione delle contravvenzioni"},{"foto":false,"t":"testo","tit":"Chi vigila: ASL, Ispettorato nazionale del lavoro e altri organi","lead":"La vigilanza sull’applicazione della normativa di salute e sicurezza è affidata principalmente alle ASL e, dal 2021, anche all’Ispettorato nazionale del lavoro in tutti i settori.","punti":["Aziende sanitarie locali (servizi di prevenzione e sicurezza negli ambienti di lavoro)","Ispettorato nazionale del lavoro: competenza estesa a tutti i settori dal D.L. 146/2021","Vigili del fuoco per i profili di prevenzione incendi","Altri organi per settori specifici (ad esempio radiazioni ionizzanti, attività minerarie, trasporti)","INAIL: assicurazione, prevenzione, ricerca e supporto alle imprese, senza funzioni di vigilanza ispettiva sulla sicurezza"],"appro":"Il coordinamento tra gli organi avviene a livello regionale nei comitati previsti dall’art. 7, per evitare sovrapposizioni dei controlli e programmare la vigilanza sui settori a maggior rischio.","rif":"D.lgs. 81/2008, artt. 7 e 13 · D.L. 21 ottobre 2021, n. 146","nar":"La vigilanza sull’applicazione della normativa di salute e sicurezza è disciplinata dall’articolo tredici del testo unico. È svolta principalmente dalle aziende sanitarie locali, attraverso i servizi di prevenzione e sicurezza negli ambienti di lavoro. Dal duemilaventuno, con il decreto-legge centoquarantasei, la competenza dell’Ispettorato nazionale del lavoro è stata estesa a tutti i settori di attività, mentre in precedenza era limitata ad alcuni ambiti come l’edilizia. Ai Vigili del fuoco spetta la vigilanza per i profili di prevenzione incendi. Per settori specifici, come le radiazioni ionizzanti, le attività minerarie o alcuni comparti dei trasporti, intervengono organi dedicati. L’Istituto nazionale per l’assicurazione contro gli infortuni sul lavoro svolge funzioni di assicurazione, prevenzione, ricerca e supporto alle imprese, ma non ha compiti di vigilanza ispettiva sull’applicazione delle norme di sicurezza. Il coordinamento tra gli organi avviene a livello regionale, nei comitati previsti dall’articolo sette, con l’obiettivo di evitare sovrapposizioni nei controlli e di programmare la vigilanza sui settori a maggior rischio.","est":true,"ancora":"L’ispezione: poteri degli organi di vigilanza e sospensione dell’attività"},{"foto":false,"t":"scenario","tit":"Due ispettori nello stesso giorno","scena":"In uno stesso stabilimento si presentano un ispettore dell’Ispettorato nazionale del lavoro e, in un secondo momento, i tecnici della ASL.","decisioni":[{"dom":"È possibile che entrambi abbiano competenza in materia di sicurezza?","opz":[["Sì: dal D.L. 146/2021 l’Ispettorato ha competenza estesa in materia di salute e sicurezza in tutti i settori, accanto alle ASL",true,"Corretto."],["No, solo la ASL",false,"La competenza è stata estesa."],["No, solo l’Ispettorato",false,"Le ASL mantengono la competenza."]]},{"dom":"Come si coordinano?","opz":[["Attraverso la programmazione coordinata a livello regionale e lo scambio di informazioni",true,"Corretto: i comitati regionali di coordinamento."],["Non si coordinano",false,"Il coordinamento è previsto."],["Decide l’impresa chi ricevere",false,"Non spetta all’impresa."]]},{"dom":"Come si comporta l’impresa?","opz":[["Collabora con entrambi, tenendo un registro delle ispezioni e delle prescrizioni ricevute",true,"Corretto."],["Rifiuta il secondo controllo",false,"Non è ammesso."],["Chiede di unificare le visite",false,"Può chiederlo, ma non è un diritto."]]}],"chiusura":"ASL e Ispettorato nazionale del lavoro vigilano entrambi sulla sicurezza, coordinandosi a livello regionale: l’impresa collabora e traccia ispezioni e prescrizioni.","nar":"Due organi di vigilanza nello stesso stabilimento. Comportati correttamente.","rif":"Art. 13 D.lgs. 81/2008 · D.L. 146/2021","est":true,"ancora":"Chi vigila: ASL, Ispettorato nazionale del lavoro e altri organi"},{"foto":false,"t":"testo","tit":"Lavoro irregolare e gravi violazioni: la sospensione dell’art. 14","lead":"L’art. 14 del D.lgs. 81/2008, riscritto dal D.L. 146/2021, consente all’Ispettorato nazionale del lavoro e alle ASL di sospendere l’attività imprenditoriale.","punti":["Presupposto: almeno il 10% dei lavoratori presenti sul luogo di lavoro impiegati senza preventiva comunicazione di instaurazione del rapporto","Presupposto: gravi violazioni in materia di salute e sicurezza individuate nell’Allegato I al D.lgs. 81/2008","La sospensione riguarda la parte dell’attività interessata dalle violazioni","Revoca subordinata alla regolarizzazione, al ripristino delle condizioni di sicurezza e al pagamento di una somma aggiuntiva","Durante la sospensione l’impresa non può contrattare con la pubblica amministrazione"],"appro":"Le gravi violazioni dell’Allegato I comprendono, ad esempio, la mancata elaborazione del documento di valutazione dei rischi, la mancata formazione e addestramento, la mancanza di protezioni contro le cadute dall’alto e l’assenza di DPI contro le cadute dall’alto.","rif":"D.lgs. 81/2008, art. 14 e Allegato I · D.L. 21 ottobre 2021, n. 146, conv. L. 215/2021","nar":"L’articolo quattordici del testo unico, riscritto dal decreto-legge centoquarantasei del duemilaventuno, disciplina il provvedimento di sospensione dell’attività imprenditoriale. Lo possono adottare l’Ispettorato nazionale del lavoro e, per i profili di salute e sicurezza, i servizi delle aziende sanitarie locali. I presupposti sono due. Il primo riguarda il lavoro irregolare: la sospensione scatta quando almeno il dieci per cento dei lavoratori presenti sul luogo di lavoro risulta occupato senza la preventiva comunicazione di instaurazione del rapporto. Il secondo riguarda le gravi violazioni in materia di salute e sicurezza elencate nell’allegato uno al testo unico, tra cui la mancata elaborazione del documento di valutazione dei rischi, la mancata formazione e addestramento dei lavoratori e la mancanza di protezioni contro le cadute dall’alto. La sospensione riguarda la parte dell’attività interessata dalle violazioni. La revoca è subordinata alla regolarizzazione dei lavoratori, al ripristino delle condizioni di sicurezza e al pagamento di una somma aggiuntiva. Durante il periodo di sospensione l’impresa non può contrattare con la pubblica amministrazione. Per il lavoratore questo strumento ha un significato preciso: le carenze di formazione e di valutazione dei rischi sono considerate così gravi da poter fermare l’attività.","est":true,"ancora":"L’ispezione: poteri degli organi di vigilanza e sospensione dell’attività"},{"foto":false,"t":"laboratorio","tit":"Laboratorio · La sospensione dell’attività","lead":"Gestisci un provvedimento di sospensione in un cantiere edile.","dossier":[["Accertamento","su 15 lavoratori presenti, 3 senza comunicazione di assunzione; nessuna protezione contro le cadute su un solaio"],["Provvedimento","sospensione della parte dell’attività interessata"]],"compiti":[{"q":"Quali presupposti sono stati accertati?","min":6,"modello":"Lavoro irregolare oltre la soglia: 3 su 15 è il 20%, oltre il 10%; gravi violazioni in materia di sicurezza, come la mancata protezione contro le cadute dall’alto, che rientrano nell’Allegato I.","criteri":["Ho calcolato il 20%","Ho collegato la caduta dall’alto all’Allegato I"]},{"q":"Che cosa serve per la revoca?","min":7,"modello":"Regolarizzazione dei lavoratori irregolari; ripristino delle condizioni di sicurezza con le protezioni contro le cadute; pagamento delle somme aggiuntive previste, ad esempio 2.500 euro per il lavoro irregolare, raddoppiate in caso di recidiva.","criteri":["Ho indicato regolarizzazione e ripristino","Ho indicato le somme aggiuntive"]},{"q":"Quali altre conseguenze ha la sospensione?","min":6,"modello":"Divieto di contrattare con la pubblica amministrazione per la durata della sospensione; riflessi sulla patente a crediti; possibili contravvenzioni e sanzioni per le violazioni accertate. Il provvedimento può essere impugnato secondo le regole previste.","criteri":["Ho indicato il divieto con la PA","Ho indicato i riflessi sulla patente"]}],"nar":"Nel laboratorio gestisci un provvedimento di sospensione dell’attività in un cantiere: presupposti, condizioni per la revoca e altre conseguenze. Confronta ogni risposta con la soluzione di riferimento.","rif":"Art. 14 e Allegato I D.lgs. 81/2008","est":true,"ancora":"Lavoro irregolare e gravi violazioni: la sospensione dell’art. 14"},{"foto":false,"t":"scenario","tit":"L’ispettore in reparto","scena":"Un ispettore dell’ASL si presenta senza preavviso e chiede di visitare il reparto saldatura e di vedere il DVR e i registri della formazione.","decisioni":[{"dom":"Come ti comporti?","opz":[["Collabori: lo accompagni, metti a disposizione i documenti e annoti ciò che viene esaminato",true,"Corretto: gli ispettori hanno poteri di accesso e di esame dei documenti."],["Gli chiedi di tornare con un appuntamento",false,"L’accesso non richiede preavviso."],["Neghi l’accesso finché non arriva il datore di lavoro",false,"Ostacolare l’ispezione è un illecito."]]},{"dom":"L’ispettore chiede di sentire due lavoratori senza la presenza dei responsabili. È ammesso?","opz":[["Sì, può assumere informazioni dai lavoratori",true,"Corretto."],["No, serve sempre un dirigente presente",false,"Non è un requisito."],["Solo con un avvocato",false,"Non è necessario."]]},{"dom":"Al termine riceve un verbale con prescrizioni. Che cosa fai?","opz":[["Organizzi l’adempimento nei termini, con responsabili e prove, e chiedi per tempo una proroga motivata se necessario",true,"Corretto: la regolarizzazione consente di estinguere le contravvenzioni."],["Lo archivi",false,"I termini decorrono."],["Contesti tutto senza adempiere",false,"Si può contestare, ma i termini vanno gestiti."]]}],"chiusura":"Collaborare all’ispezione, consentire l’accesso a luoghi, documenti e lavoratori, gestire le prescrizioni nei termini: così l’impresa tutela sé stessa e i lavoratori.","nar":"Un’ispezione senza preavviso. Gestisci la visita e le conseguenze.","rif":"Art. 13 D.lgs. 81/2008 · D.lgs. 758/1994","est":true,"ancora":"L’ispezione: poteri degli organi di vigilanza e sospensione dell’attività"},{"t":"caso","tit":"Esercitazione 1 · Caso di studio","scena":"L'RSPP esterno di un'azienda metalmeccanica, durante il sopralluogo annuale, nota che la pressa piegatrice ha la barriera fotoelettrica disattivata. Non lo annota nel verbale perché il capo reparto assicura che verrà riattivata. Un mese dopo un operatore si infortuna alla mano.","domanda":"Quale profilo di responsabilità riguarda l'RSPP?","opz":[["Nessuno: l'RSPP è un consulente senza poteri",false,"No: la giurisprudenza riconosce la responsabilità in concorso per omessa segnalazione."],["Può rispondere in concorso, avendo omesso di segnalare per iscritto al datore di lavoro un rischio grave che aveva rilevato",true,"Corretto: la segnalazione documentata è il primo strumento di tutela, per i lavoratori e per lo stesso RSPP."],["Risponde solo il lavoratore infortunato",false,"No: la protezione disattivata è una carenza organizzativa."]],"nar":"Prima esercitazione. Una protezione disattivata vista e non segnalata: quale responsabilità per l'RSPP?","p":1.3},{"foto":false,"t":"applica","tit":"Il quadro normativo nella tua attività","lead":"Verifica come applichi il quadro normativo nel tuo lavoro.","voci":["Consulto fonti ufficiali per gli aggiornamenti","Tengo un registro delle novità normative","Uso le norme tecniche armonizzate","Conosco le buone prassi validate","Documento le segnalazioni al datore di lavoro","Conosco gli organi di vigilanza competenti"],"campo":"La fonte che consulterai regolarmente da oggi","esempio":"Es.: newsletter del Ministero del Lavoro e Gazzetta ufficiale","min":3,"nar":"Verifica come applichi il quadro normativo nel tuo lavoro e indica la fonte che consulterai regolarmente.","est":true,"ancora":"Esercitazione 1 · Caso di studio"},{"t":"sintesi","tit":"Sintesi dell'unità A1","voci":["Dalla prescrizione tecnica alla prevenzione organizzata","Fonti: Costituzione, diritto UE, art. 2087 c.c., D.lgs. 81/2008, norme tecniche","Definizioni dell'art. 2 e misure generali di tutela dell'art. 15","Responsabilità penale, civile e dell'ente; esimente del modello organizzativo","Sistema istituzionale e procedure di vigilanza"],"nar":"Riepilogo dell'unità A uno: l'evoluzione della normativa, le fonti, le definizioni, le misure generali di tutela, le responsabilità e il sistema istituzionale.","p":1},{"t":"verifica","tit":"Verifica intermedia · Unità A1","soglia":6,"domande":[["La direttiva quadro europea in materia di sicurezza è la:",["89/391/CEE","2006/42/CE","2014/34/UE","98/24/CE"],0,"Recepita nel D.lgs. 626/1994 e poi nel D.lgs. 81/2008."],["Il rischio è definito come:",["Probabilità di raggiungimento del livello potenziale di danno","Proprietà intrinseca","Danno certo","Infortunio"],0,"Art. 2, lett. s)."],["Le misure collettive rispetto a quelle individuali:",["Hanno priorità","Sono equivalenti","Sono residuali","Sono vietate"],0,"Art. 15, lett. i)."],["L'esimente per l'ente è:",["Modello di organizzazione e gestione efficacemente attuato","Polizza assicurativa","Certificazione ISO 9001","DURC"],0,"Art. 30 D.lgs. 81/2008."],["Il reato contravvenzionale si estingue con:",["Adempimento alla prescrizione e pagamento di un quarto del massimo","Pagamento del doppio","Ricorso","Nessuna procedura"],0,"D.lgs. 758/1994."],["Per l’omicidio colposo con violazione dell’art. 55, c. 2 l’ente subisce una sanzione pecuniaria di:",["100 quote","250 quote","1.000 quote","Nessuna"],2,"Art. 25-septies D.lgs. 231/2001."],["Nei reati colposi l’interesse o vantaggio dell’ente consiste tipicamente:",["Nell’aumento di fatturato","Nel risparmio di costi o tempi per la mancata adozione delle misure","Nella pubblicità","Non è rilevante"],1,"Giurisprudenza consolidata."],["Le direttive di prodotto realizzano:",["Requisiti minimi derogabili in meglio","Un’armonizzazione completa per l’immissione sul mercato","Solo raccomandazioni","Obblighi per i lavoratori"],1,"Mercato interno."]],"nar":"Verifica intermedia dell'unità A uno.","p":1.4}]}],"testFinale":{"domande":30,"soglia":70,"tentativi":3,"banca":[]},"prova":true};
